import json, re, chess, random

def all_legal_next_positions(fen):
    for pattern, repl in json.load(open("/app/re.json")):
        fen = re.sub(pattern, repl, fen)
    return fen.split("\n")

def run_solution(fen):
    return [" ".join(x.split(" ")[:-2]) for x in all_legal_next_positions(fen)]

def ref_moves(board):
    ref = set()
    for move in board.legal_moves:
        if move.promotion and move.promotion != chess.QUEEN:
            continue
        bc = board.copy()
        bc.push(move)
        ref.add(" ".join(bc.fen().split(" ")[:-2]))
    return ref

random.seed(12345)
fail_count = 0
test_count = 0
for game in range(50):
    board = chess.Board()
    for ply in range(40):
        if board.turn == chess.WHITE:
            fen = board.fen()
            our = set(run_solution(fen))
            ref = ref_moves(board)
            test_count += 1
            if our != ref:
                fail_count += 1
                print(f"FAIL game={game} ply={ply} fen={fen} our={len(our)} ref={len(ref)}")
                print("  missing:", list(ref - our)[:5])
                print("  extra:", list(our - ref)[:5])
                if fail_count >= 5:
                    break
        moves = list(board.legal_moves)
        # weight queen promotions only
        board.push(random.choice(moves))
    if fail_count >= 5:
        break
print(f"tested {test_count} positions, failures {fail_count}")
